        'flowchart LR\n  A["request address"] --> B["tag + set + offset"]\n  B --> C["tag compare"]\n  C -->|"hit"| D["banked data array"]\n  C -->|"miss"| E["miss-status entry"]\n  E --> F["memory refill"]\n  F --> D',
