        'flowchart LR\n  A["block request"] --> B["thread/warp slots"]\n  A --> C["register budget"]\n  A --> D["shared-memory budget"]\n  B --> E["resident blocks"]\n  C --> E\n  D --> E\n  E --> F["scheduler hides latency"]',
