        'flowchart LR\n  A["SM updates"] --> B["L1/L2 + NoC"]\n  B --> C["atomic read-modify-write"]\n  C --> D["memory controller / PHY"]\n  E["clock + power delivery"] --> A\n  E --> B\n  E --> C',
