        'flowchart LR\n  A["kernel launch"] --> B["grid of blocks"]\n  B --> C["threads grouped into warps"]\n  C --> D["predicate mask"]\n  D --> E["execute path A"]\n  D --> F["execute path B"]\n  E --> G["reconverge"]\n  F --> G',
